    Returns True if a UPI payment amount is valid, otherwise False.

    A valid amount must be greater than 0, at most 100,000, and have at most 2 decimal places.
    """
    # Check if the amount is greater than 0
    if amount <= 0:
        return False

    # Round to 2 decimal places and check if it's less than or equal to 100,000
    if round(amount, 2) <= 100000:
        return True
    else:
