def inr_format(amount):
    # Handle single-digit numbers directly
    if amount < 1000:
        return str(amount)

    # Split the number into groups of three digits
    formatted_amount = ''.join(str(amount // 1000) * 3)[::-1]

    # Insert commas as separators
    return formatted_amount.replace(',', '')

