def ondc_next_state(current_state, event):
    transitions = {
        'Created': {'confirm': 'Accepted'},
        'Accepted': {'pack': 'Packed'},
        'Packed': {'ship': 'Shipped'},
        'Shipped': {'deliver': 'Delivered'},
        'Delivered': {'cancel': 'Cancelled'},
        'cancel': {'Created', 'Accepted', 'Packed'}
    }

    if current_state in transitions and (event, current_state) in transitions[current_state]:
        return transitions[current_state][event]
    elif current_state == 'cancel' and (current_state, event) in transitions['cancel']:
        return 'Cancelled'
    else:
        return None

