def emi(P, i, n):
    # Convert annual interest rate from percentage to decimal
    i_dec = i / 100.0

    # Handle the case when the interest rate is 0
    if i_dec == 0:
        return round(P / n, 2)

    # Calculate EMI using the formula for monthly compounding
    emi = round(P * i_dec * (1 + i_dec) ** n / ((1 + i_dec) ** n - 1), 2)

    return emi

