    params = uri.split('?pa=')
    if not params:
        return None

    # Split each parameter by '=' to separate key-value pairs
    for param in params[1].split('&'):
        key, value = param.split('=')
        if key == 'am':
            return float(value)

    # Return None if 'am' is not found
    return None

